		doc.text(metaParts.join("   •   "), marginX, curY);
		curY += 4.5;
		doc.setFontSize(7.5);
		doc.setTextColor(...textMuted);
		const provParts = [];
		if (report.status === "Modified") provParts.push("Status: Modified Analysis");
		else provParts.push("Status: Original Analysis");
		if (report.copiedFromId) provParts.push(`Copied from: ${report.copiedFromId}`);
		if (report.createdAt) provParts.push(`Created: ${new Date(report.createdAt).toLocaleString()}`);
		if (report.updatedAt) provParts.push(`Updated: ${new Date(report.updatedAt).toLocaleString()}`);
		doc.text(provParts.join("   ·   "), marginX, curY);
		curY += 3.5;
		doc.setDrawColor(...ruleGray);
		doc.setLineWidth(.3);
		doc.line(marginX, curY, 199, curY);
